SELECT 'batch_008_6cfb5fdf_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0e5df05d-8f8','sm-upload-229fabb8-45d','sm-upload-5ef32f7a-887','sm-upload-741e30e9-2a8','sm-upload-9a2b0423-b81','sm-upload-c44b0f7c-761','sm-upload-cc9304d5-527','sm-upload-d0988a3b-ddc','sm-upload-f994d933-d13','sm-upload-fd16b9a8-697') AND album_id='al-d302ed534fe12110d275ff786cfb5fdf') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0e5df05d-8f8','sm-upload-229fabb8-45d','sm-upload-5ef32f7a-887','sm-upload-741e30e9-2a8','sm-upload-9a2b0423-b81','sm-upload-c44b0f7c-761','sm-upload-cc9304d5-527','sm-upload-d0988a3b-ddc','sm-upload-f994d933-d13','sm-upload-fd16b9a8-697') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-d302ed534fe12110d275ff786cfb5fdf' AND name='兰音.2024.《形神合一》') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-d302ed534fe12110d275ff786cfb5fdf') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-d302ed534fe12110d275ff786cfb5fdf') AS calculated_size;
